// The agent skill must stay self-contained and in step with the sources: scripts/validate.mjs, scripts/capture.mjs
// and assets/planwalk.html are generated by npm run build:skill. These tests fail when one of them goes stale,
// when the skill behaves differently from the repository tools, when SKILL.md names a file or a command that does
// not exist, or when the skill does not work after being copied alone to another place.
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { copyFileSync, cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../../', import.meta.url));
const skill = join(root, 'skill/planwalk');
const GENERATED = ['scripts/validate.mjs', 'scripts/capture.mjs', 'assets/planwalk.html'];
const MAX = 64 * 1024 * 1024; // spawnSync stops a child whose output passes 1 MiB by default
const run = (...args) => spawnSync(process.execPath, args, { encoding: 'utf8', timeout: 110000, maxBuffer: MAX });
const runIn = (cwd, ...args) => spawnSync(process.execPath, args, { encoding: 'utf8', timeout: 110000, maxBuffer: MAX, cwd });
const tmp = mkdtempSync(join(tmpdir(), 'planwalk-skill-'));
test.after(() => rmSync(tmp, { recursive: true, force: true }));
const fx = (rel) => join(root, rel);
const flat = () => JSON.parse(readFileSync(fx('examples/flat-1.plan.json'), 'utf8'));

// The skill folder copied alone to an unrelated place: no dist/, no tools/, no node_modules anywhere near it, a path with a
// space, a hash and a percent sign (all of them have to survive a file:// URL), and a working directory that is not the repository.
let copied;
const standalone = () => {
  if (!copied) {
    copied = join(tmp, 'else where #1 %20', 'planwalk');
    cpSync(skill, copied, { recursive: true });
  }
  return copied;
};
const work = join(tmp, 'work');
mkdirSync(work);
copyFileSync(fx('examples/flat-1.plan.json'), join(work, 'flat.plan.json'));
copyFileSync(fx('examples/duplex-1.plan.json'), join(work, 'duplex.plan.json'));

const chrome = ['/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ...['google-chrome', 'chromium', 'chromium-browser'].map((c) => (spawnSync('which', [c]).status === 0 ? c : null))]
  .filter(Boolean).find((c) => !c.includes('/') || existsSync(c));
const skip = !chrome ? 'Chrome or Chromium not found' : typeof WebSocket === 'undefined' ? 'Node 22 or newer is needed for the global WebSocket' : false;

test('generated skill files are byte for byte a fresh build (run npm run build:skill when this fails)', () => {
  const fresh = join(tmp, 'fresh');
  const r = runIn(tmp, fx('tools/build-skill.mjs'), '--out', fresh); // from another directory: the output must not depend on it
  assert.equal(r.status, 0, `${r.stdout}\n${r.stderr}`);
  for (const f of GENERATED) {
    assert.ok(existsSync(join(skill, f)), `skill/planwalk/${f} is missing: run npm run build:skill and commit it`);
    assert.ok(readFileSync(join(skill, f)).equals(readFileSync(join(fresh, f))), `skill/planwalk/${f} is stale: run npm run build:skill and commit it`);
  }
});

test('the bundled validator imports only node: built-ins', () => {
  const text = readFileSync(join(skill, 'scripts/validate.mjs'), 'utf8');
  assert.match(text, /^#!\/usr\/bin\/env node\n\/\/ Generated by npm run build:skill/);
  const specifiers = [...text.matchAll(/^import\b[^;]*?\bfrom\s*["']([^"']+)["']/gm)].map((m) => m[1]);
  assert.ok(specifiers.length > 0, 'no import found, the pattern above no longer matches the bundle');
  assert.deepEqual(specifiers.filter((s) => !s.startsWith('node:')), [], 'a relative or package import would break the skill when it is copied elsewhere');
  assert.doesNotMatch(text, /\brequire\(|\bimport\(/);
});

test('the skill validator prints exactly what tools/validate.mjs prints, on good and on broken plans', () => {
  const files = [];
  for (const dir of ['examples', 'tests/fixtures']) for (const n of readdirSync(fx(dir)).filter((x) => x.endsWith('.plan.json')).sort()) files.push(fx(`${dir}/${n}`));
  const ghost = flat(); ghost.levels[0].openings[0].wall = 'ghost';
  const area = flat(); area.levels[0].rooms[0].area = 99;
  const variants = { 'ghost.json': JSON.stringify(ghost), 'area.json': JSON.stringify(area), 'notjson.json': '{ nope' };
  for (const [name, text] of Object.entries(variants)) {
    const f = join(tmp, name);
    writeFileSync(f, text);
    files.push(f);
  }
  const seen = new Set();
  for (const f of files) {
    for (const extra of [[], ['--json'], ['--strict']]) {
      const a = run(fx('tools/validate.mjs'), f, ...extra);
      const b = run(join(skill, 'scripts/validate.mjs'), f, ...extra);
      assert.equal(b.status, a.status, `${f} ${extra}: exit code`);
      assert.equal(b.stdout, a.stdout, `${f} ${extra}: output`);
      for (const m of a.stdout.matchAll(/\b([EW]\d{3})\b/g)) seen.add(m[1]);
    }
  }
  for (const c of ['E001', 'E005', 'W102']) assert.ok(seen.has(c), `the comparison never produced ${c}, so it proves little`);
});

test('a large --json report comes through a pipe whole, from the tools and from the skill (process.exit would cut it)', () => {
  // The validator lists at most 100 issues of one code, so the report is made big with several codes at once.
  const big = flat();
  const L = big.levels[0];
  for (let i = 0; i < 300; i++) L.openings.push({ id: `x${i}`, wall: 'ghost', type: 'window', offset: 0.5, width: 1 }); // E005
  for (let i = 0; i < 250; i++) L.walls.push({ id: `z${i}`, from: [1, 1], to: [1, 1] }); // E004
  for (let i = 0; i < 250; i++) L.walls.push({ id: 'dup', from: [2, 2], to: [3, 3] }); // E003
  for (let i = 0; i < 100; i++) L.rooms.push({ id: `q${i}`, name: 'Q', polygon: [[0, 0], [1, 1]] }); // E002 (two points)
  const f = join(tmp, 'big.plan.json');
  writeFileSync(f, JSON.stringify(big));
  for (const cli of [fx('tools/validate.mjs'), join(skill, 'scripts/validate.mjs')]) {
    const r = run(cli, f, '--json');
    assert.equal(r.status, 1, cli);
    assert.ok(r.stdout.length > 100000, 'the report should be big enough to overflow a pipe buffer');
    const report = JSON.parse(r.stdout);
    for (const code of ['E003', 'E004', 'E005']) assert.equal(report.errors.filter((e) => e.code === code).length, 101, `${cli}: ${code} (100 listed and one closing issue)`);
  }
});

test('SKILL.md names the tools, every path and command it names exists, and it does not send the reader to the repository', () => {
  const md = readFileSync(join(skill, 'SKILL.md'), 'utf8');
  const named = new Set([...md.matchAll(/(?<![\w.-])((?:scripts|assets|reference)\/[\w.-]+\.(?:mjs|html|md))/g)].map((m) => m[1]));
  for (const f of [...GENERATED, 'scripts/embed.mjs', 'reference/plan-format.md', 'reference/reading-plans.md']) assert.ok(named.has(f), `SKILL.md should mention ${f}`);
  for (const f of named) assert.ok(existsSync(join(skill, f)), `SKILL.md names ${f}, which is not in the skill folder`);

  const commands = [...md.matchAll(/`node (\S+)[^`]*`/g)].map((m) => m[1]);
  for (const c of commands) {
    assert.match(c, /^<skill-dir>\/scripts\/[\w.-]+\.mjs$/, `a command must start from <skill-dir>/scripts/: ${c}`);
    assert.ok(existsSync(join(skill, c.replace('<skill-dir>/', ''))), `${c} does not exist`);
  }
  for (const t of ['validate', 'capture', 'embed']) assert.ok(commands.includes(`<skill-dir>/scripts/${t}.mjs`), `no command for ${t}`);
  assert.match(md, /`<skill-dir>` is the folder that contains this SKILL\.md/);
  assert.doesNotMatch(md, /\btools\/(?:validate|capture)\.mjs|\bdist\/planwalk|\bskill\/planwalk\b|clone of the repository/);
});

test('the skill works when copied alone to another place: validate and embed find everything inside it', () => {
  const dir = standalone();
  const v = runIn(work, join(dir, 'scripts/validate.mjs'), 'flat.plan.json');
  assert.equal(v.status, 0, `${v.stdout}\n${v.stderr}`);
  assert.match(v.stdout, /0 errors, 0 warnings/);

  const e = runIn(work, join(dir, 'scripts/embed.mjs'), 'flat.plan.json', 'flat.html');
  assert.equal(e.status, 0, `${e.stdout}\n${e.stderr}`);
  assert.match(e.stdout, /from planwalk\.html with plan/, 'embed.mjs should have used assets/planwalk.html');
  const html = readFileSync(join(work, 'flat.html'), 'utf8');
  assert.deepEqual(JSON.parse(/<script type="application\/json" id="planwalk-plan">([\s\S]*?)<\/script>/.exec(html)[1]), flat());
  assert.ok(!html.includes('<script type="application/json" id="planwalk-samples">'), 'the delivered file should not carry sample plans');
  assert.ok(html.length > 500000, 'the viewer code is missing from the delivered file');
});

test('capture.mjs in the copied skill finds its viewer in assets/ and renders it', { skip, timeout: 120000 }, () => {
  const dir = standalone();
  const r = runIn(work, join(dir, 'scripts/capture.mjs'), 'duplex.plan.json', '--out', 'shots', '--views', 'top', '--no-panel', '--chrome', chrome, '--size', '960x540');
  assert.equal(r.status, 0, `${r.stdout}\n${r.stderr}`);
  assert.match(r.stdout, /load: ok=true, 0 errors, 0 warnings/);
  assert.match(r.stdout, /console: 0 errors, 0 warnings/);
  assert.ok(statSync(join(work, 'shots', 'top.png')).size > 5000, 'top.png is too small to be a render');
});

test('the commands in the steps of SKILL.md run as written (placeholders filled in) from another directory', { timeout: 120000 }, () => {
  const dir = standalone();
  const md = readFileSync(join(skill, 'SKILL.md'), 'utf8');
  const commands = [...md.matchAll(/`node (<skill-dir>\/scripts\/[\w.-]+\.mjs)([^`]*)`/g)].map((m) => ({ script: m[1].replace('<skill-dir>', dir), args: m[2].split(/\s+/).filter(Boolean) }));
  const fill = (a) => a.replace('plan.json', 'flat.plan.json').replace('planwalk-<name>.html', 'planwalk-steps.html');
  const ran = [];
  for (const { script, args } of commands) {
    const isCapture = script.endsWith('capture.mjs');
    if (isCapture && skip) continue;
    const r = runIn(work, script, ...args.map(fill), ...(isCapture ? ['--views', 'top', '--chrome', chrome, '--size', '960x540'] : []));
    assert.equal(r.status, 0, `${script} ${args.join(' ')}\n${r.stdout}\n${r.stderr}`);
    ran.push(script.split('/').pop());
  }
  assert.ok(ran.includes('validate.mjs') && ran.includes('embed.mjs'), `only ran ${ran}`);
  assert.ok(statSync(join(work, 'planwalk-steps.html')).size > 500000, 'step 10 did not write the viewer file');
});
